import pyomo.environ as pyo

DATA = {
    "processes": ["J", "P"],
    "metal": {"J": 5, "P": 9},          # units of metal per run
    "resources": ["water", "pollution"],
    "usage": {
        "water": {"J": 8, "P": 6},       # water units per run
        "pollution": {"J": 3, "P": 5},   # pollution units per run
    },
    "limits": {
        "water": 1500,
        "pollution": 1350,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.PROCESSES = pyo.Set(initialize=d["processes"], ordered=True)
    model.RESOURCES = pyo.Set(initialize=d["resources"], ordered=True)

    # --- Variables ---
    # Number of times each process is performed (indivisible runs -> integers).
    model.x = pyo.Var(
        model.PROCESSES,
        domain=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # --- Objective: maximize total metal extracted ---
    def obj_rule(m):
        return sum(d["metal"][p] * m.x[p] for p in m.PROCESSES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # --- Constraints: one per resource availability sentence ---
    def resource_rule(m, r):
        return sum(
            d["usage"][r][p] * m.x[p] for p in m.PROCESSES
        ) <= d["limits"][r]

    model.resource_limit = pyo.Constraint(model.RESOURCES, rule=resource_rule)

    return model
